import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG 转 PNG 是个简单任务，但值得做对。正确的转换会把文件重写成真正的 PNG，而不是改了名的 JPG。</p>\n<p>每张只要几秒，一次最多能转二十张图片。一切都在浏览器里运行，不用安装。</p>\n<p>这篇指南按步骤走，讲清使用结果之前该检查什么。</p>\n<h2 id=\"before-you-start\">开始之前：先想清为什么要转</h2>\n<p>问问自己，PNG 是干什么用的。编辑、设计工作、文字叠加是好理由。让照片更清晰或更小不是，因为 PNG 两者都做不到。</p>\n<p>确认 PNG 是不是真的必需。有些工具要求它，但很多工具接受 JPG 或 WebP，照片用它们小得多。</p>\n<p>找到画质最好的 JPG 原文件。PNG 会原样保留它，瑕疵也一并保留，所以从最高质量的副本开始。</p>\n<p>每张文件最大接受 25MB。涵盖高分辨率相机导出和宽幅数字作品，不用任何准备。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 JPG 转 PNG 工具</h2>\n<p>在浏览器里打开<a href=\"/zh/jpg-zhuan-png/\">JPG 转 PNG 工具</a>。Windows、Mac、Linux、ChromeOS、安卓、iOS 上都能用。</p>\n<p>你会看到上传区域和转换按钮。没有画质滑块，因为 PNG 是无损的，没有画质可选。</p>\n<p>不用注册账号，什么都不上传。转换在你的设备上进行，个人照片和扫描件都很看重这一点。</p>\n<p>手机上也一样，在移动浏览器里用。点上传区域，从相册里选照片。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 JPG 文件</h2>\n<p>把 JPG 文件拖到上传区域，或者点一下打开文件选择器。.jpg 和 .jpeg 扩展名都接受。</p>\n<p>一次最多能上传二十个文件。每张都会显示成一张卡片，带名字、尺寸和大小，确认传的是正确的文件。</p>\n<p>检查每张卡片上的尺寸。PNG 会精确保留 JPG 的像素宽高，传错的文件在这里很容易发现。</p>\n<p>电脑上也可以用 Ctrl+V 粘贴复制的图片。JPG 在剪贴板里、从别的软件复制过来时，这个办法很方便。</p>\n<h2 id=\"step-3-convert\">第 3 步：转换文件</h2>\n<p>点“转换”按钮。工具解码每张 JPG，画到画布上，编码成 PNG。</p>\n<p>转换很快，通常每张一两秒。文件更大时稍久一点，因为无损编码的像素更多。</p>\n<p>每张卡片都会更新，显示新 PNG 的大小和原来 JPG 的大小。照片的 PNG 往往大得多，常常是 JPG 的五到十倍，这是预料之中的。</p>\n<p>某个文件失败时，读一下错误提示。损坏的 JPG 或名字不对的文件是最常见的原因，其余批量继续转换。</p>\n<h2 id=\"step-4-compare\">第 4 步：对比结果</h2>\n<p>点卡片上的“对比”，打开并排查看器。它把 JPG 和 PNG 放在一起，让你确认零颜色偏移。</p>\n<p>仔细看边缘和文字。PNG 应该和 JPG 一模一样，因为转换精确保留了每个像素。</p>\n<p>查看器里也检查尺寸。宽高应该和原 JPG 精确一致，没有裁剪、没有缩放。</p>\n<p>有任何不同，说明哪里出问题了。重新上传原 JPG 再转一次，别试图去修 PNG。</p>\n<h2 id=\"step-5-download\">第 5 步：下载 PNG 文件</h2>\n<p>点单张卡片上的“下载”，保存一张 PNG。文件名保留原名，换成 .png 后缀。</p>\n<p>批量时点“全部下载”，拿到一个装着所有转好 PNG 的 ZIP 包。比一张一张下载快得多。</p>\n<p>使用之前检查一次下载好的文件。在看图软件里打开一张 PNG，确认样子没问题，确认它能在需要的应用里打开。</p>\n<p>原 JPG 也留着。PNG 是工作副本，JPG 依然是同一张图的更小、更便携的版本。</p>\n<ol>\n<li>打开 JPG 转 PNG 工具，上传 JPG 文件。</li>\n<li>点“转换”，等每张卡片完成。</li>\n<li>对比一张卡片，确认颜色完全一致。</li>\n<li>下载单张 PNG，或者整批打成 ZIP 下载。</li>\n</ol>\n<h2 id=\"converting-a-batch\">一次转换二十张</h2>\n<p>在文件选择器里一次选最多二十张 JPG。它们一起进入队列，一次点击全部转换。</p>\n<p>批量运行时留意“变化”一栏。它清楚显示文件体积增长了多少，哪些文件长得最多一目了然。</p>\n<p>照片长得最多，因为它们的纹理存成 PNG 很难压缩。简单扫描件和图形长得少得多，因为平坦区域压缩得很好。</p>\n<p>批量打成 ZIP 下载，解压到新文件夹。PNG 和原 JPG 混在一个文件夹里，以后会搞混。</p>\n<h2 id=\"checking-file-size\">发送前检查文件大小</h2>\n<p>一定对照限制检查 PNG 大小。上传上限 5MB 的表格，可能拒收一个从 1MB JPG 变来的 PNG。</p>\n<p>PNG 太大时，重新想想 PNG 是不是真的必需。WebP 常常是更好的折中，无损画质、体积却小得多。</p>\n<p>邮件附件里的大 PNG 批量可能超限。改发 JPG，或者转换后压缩 PNG，对方接受的话就行。</p>\n<p>每张卡片上的“变化”一栏清楚显示增长。用它判断这次转换值不值得多花的字节。</p>\n<h2 id=\"using-png-for-editing\">用 PNG 做编辑</h2>\n<p>在你选的编辑器里打开 PNG。Photoshop、Figma、Canva、PowerPoint 都原生接受 PNG，无损格式经得起反复保存。</p>\n<p>在 PNG 版本上加文字、标注或叠加层。每次保存都和上次一样锐利，不会累积损伤。</p>\n<p>完成的结果按目的地需要的格式导出。网页要 WebP 或 JPG，打印店可能就要 PNG 本身。</p>\n<p>导出后留着 PNG 原稿。以后需要别的导出版本时，可以从 PNG 做，不用重新打开原 JPG。</p>\n<h2 id=\"fixing-problems\">常见问题怎么解决</h2>\n<p>PNG 出来比预期大得多，照片就是这样，很正常。PNG 精确存储每个像素，细节丰富的照片需要很多字节。</p>\n<p>颜色看起来偏移了，源 JPG 可能用了 CMYK 打印颜色。换 RGB 导出版本再转，或者使用前仔细检查结果。</p>\n<p>文件转失败，检查它是不是真正的 JPG。名为 .jpg、实际却是 WebP 或 PNG 的文件会让解码器糊涂，改对名字就能解决。</p>\n<p>方向看起来不对，JPG 的方向数据可能不寻常。先在看图软件里打开 JPG，确认显示正确，再转换。</p>\n<h2 id=\"mobile-tips\">手机与平板小技巧</h2>\n<p>手机上点上传区域，从相册里选 JPG。转换在手机上运行，PNG 下载到设备里。</p>\n<p>手机上的批量保持小一点，大 PNG 在移动处理器上编码很花时间。一次五个文件很舒服，二十个就慢了。</p>\n<p>下载的文件在手机的“下载”文件夹里。iPhone 去“文件”应用里找，安卓去文件管理器里找。</p>\n<p>批量很大时用电脑。更快的处理器、更大的屏幕，二十个文件管理起来容易得多。</p>\n<h2 id=\"old-family-photos\">转换老家庭照片</h2>\n<p>老家庭照片常常扫描成 JPG，转成 PNG 能得到无损工作副本，用于修复。PNG 原样保留扫描件，瑕疵也一并保留，不再叠加损伤。</p>\n<p>从最好的扫描件开始。600 DPI 的高分辨率扫描能捕捉修复需要的细节，低分辨率扫描件换什么格式都改善不了。</p>\n<p>修复开始时转换一次 PNG。去灰尘、调颜色等所有编辑都在 PNG 版本上做，它经得起反复保存。</p>\n<p>修复好的结果导出成 JPG 分享。家人拿到小文件、哪里都能打开，PNG 原稿留在档案里供以后使用。</p>\n<p>PNG 原稿起清楚的名字、带上日期。grandma-wedding-1962-restored.png 这样的名字几十年后还有用，scan001.png 这样的名字就没有。</p>\n<h2 id=\"screenshots-for-manual\">给说明书转换截图</h2>\n<p>用户手册里满是截图，这些截图在多轮编辑中必须保持可读。开始时转成 PNG，能保护文字。</p>\n<p>截图用能达到的最高分辨率拍。视网膜截图像素翻倍，手册印出来后文字依然锐利。</p>\n<p>加标注之前，把每张截图转成 PNG。加在 PNG 上的箭头、圆圈、标签保持清晰，同样标注加在 JPG 上，每保存一次就软一点。</p>\n<p>PNG 截图按章节放进文件夹。每章一个文件夹、图片编号排列，找起来容易，手册按顺序自己就搭起来了。</p>\n<p>完成的手册导出成 PDF，里面放 PNG 图片。PDF 里的文字保持锐利，读者不用眯着眼睛也能跟上每一步。</p>\n<h2 id=\"images-for-designer\">给设计师转换图片</h2>\n<p>设计师偏爱 PNG 文件，因为它们在 Photoshop、Figma、Illustrator 里原生打开。发给设计师的 JPG 常常反正要转成 PNG，发送 PNG 能省一步。</p>\n<p>发送前转换好图片，名字起清楚。hero-photo.png 能告诉设计师它是什么，IMG_4821.png 什么都告诉不了。</p>\n<p>发送手头最高质量的版本。设计师拿低画质 JPG 工作，再厉害也做不出锐利的结果。</p>\n<p>原 JPG 也一起发，万一设计师需要它们。一个文件夹里两种格式都有，设计师有选择，不用请你重发。</p>\n<p>项目开始前就商定交付格式。关于 JPG 和 PNG 的简短沟通，能防止以后出现一文件夹格式错误的文件。</p>\n<h2 id=\"product-shots-editing\">给编辑用的产品图转换</h2>\n<p>产品照片上网店之前需要编辑。裁剪、清理背景、调颜色，从 PNG 原稿做都比从 JPG 做效果好。</p>\n<p>编辑开始时，把产品 JPG 转换一次 PNG。所有调整都在 PNG 版本上做，反复保存也不会退化。</p>\n<p>先编辑一张产品照片，和团队确认效果。一个确认过的例子能定下整个目录的标准，其余照片照着同一个风格走。</p>\n<p>完成的产品图导出成 WebP 或 JPG 上网站。网店需要小文件、加载快，PNG 原稿留在档案里。</p>\n<p>PNG 原稿按产品和日期整理好。清楚的文件夹结构，商品页面需要更新时找产品图很容易。</p>\n<h2 id=\"images-for-print\">给打印用的图片转换</h2>\n<p>打印工作需要手头最高的画质，带文字的图片用 PNG 更安全。海报、传单、小册子上的锐利字，印出来从 PNG 很干净。</p>\n<p>转换前检查分辨率。1000 像素的图片印 10 英寸只有 100 DPI，纸上看起来发软，和格式无关。</p>\n<p>图片全分辨率转成 PNG，再发给打印店。打印店需要时可以缩小，但它加不出本来没有的细节。</p>\n<p>发送前问问打印店的颜色配置文件。配置文件不对的 PNG 可能印出偏移的颜色，打印店能建议正确的设置。</p>\n<p>重要任务先印一张测试。先印一张小的，确认颜色和锐利度，再决定大订单。</p>\n<h2 id=\"images-for-school-assignment\">给学校作业转换图片</h2>\n<p>学校作业常常需要网上的图片，那些图片通常是 JPG。转成 PNG 能得到无损工作副本，用于裁剪和标注。</p>\n<p>加进作业之前，把图片转成 PNG。PNG 经得起反复编辑，JPG 每次保存都会给文字和图表多一点损伤。</p>\n<p>作业图片很多时，整批一次转换。批量转换只要几分钟，PNG 做好就能拖进文档。</p>\n<p>转换后检查图片。快速看一眼每张，确认显示正常，提交当天作业里就不会有破损图片。</p>\n<p>作业里注明图片来源。转换过的图片依然属于它的创作者，规范的引用是良好的学术习惯。</p>\n<p>整个流程就是这样：上传、转换、对比、下载。想了解背景，请读<a href=\"/zh/blog/jpg-zhuan-png-wanquan-zhinan/\">JPG 转 PNG 完全指南</a>；透明问题请看<a href=\"/zh/blog/jpg-vs-png-touming-beijing-duibi/\">JPG 与 PNG：什么时候透明背景重要</a>。需要更小、而不是更大的文件时，<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>就是该用的工具。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"一次能把多少张 JPG 转成 PNG？","answer":"一次批量最多能转换二十张 JPG 文件，打成一个 ZIP 下载。每张独立转换，一张坏图不会拖垮其余文件。文件更多时，分几次、每次二十张跑。"},{"question":"JPG 转 PNG 能不让文件变大吗？","answer":"基本不能。PNG 是无损的，必须精确存储每个像素，照片从 JPG 转来几乎总是大好几倍。文件大小重要时，用 WebP 代替，画质高、体积却小得多。"},{"question":"JPG 转 PNG 离线能用吗？","answer":"页面在浏览器里加载好之后，转换在本地运行，不需要联网。只有第一次打开页面时需要网络。之后在关掉标签页之前，都可以离线转换 JPG。"},{"question":"转好的 PNG 能在 Photoshop 和 Canva 里打开吗？","answer":"可以。PNG 是设计工具的通用格式，能在 Photoshop、Illustrator、Figma、Canva、PowerPoint 和所有现代浏览器里打开。转好的 PNG 是标准文件，没有特殊要求。"},{"question":"PNG 太大传不上去怎么办？","answer":"先确认 PNG 是不是真的必需。目的地接受 WebP 或 JPG 时，换其中一种，文件会小得多。PNG 非要不可时，转换前先用尺寸调整工具缩小图片，像素少了，PNG 也就小了。"},{"question":"JPG 截图能转成 PNG 做标注吗？","answer":"可以，而且这是这个工具最好的用途之一。转成 PNG 的截图在多轮标注、裁剪、反复保存中保持锐利。在 PNG 版本上加箭头和文字，再导出完成的结果分享出去。"}];
